root=fileparts(fileparts(fileparts(mfilename('fullpath')))); cd(root); addpath(fullfile(root,'pipeline')); init_paths(root); addpath(fullfile(root,'experiment_manager'));
names=unique({'test_geometry_consistency_repair','test_candidate_parameter_repair','test_table_task_consistency_repair','test_frozen_scene_identity_repair','test_rotated_table_task_transform','test_coordinate_roundtrip','test_main_robot_unification','test_scene_layout_inside_map','test_scene_layout_no_overlap','test_experiment_protocol_repair','test_evidence_metric_contract','test_navigation_endpoint_fidelity','test_footprint_sparse_edge_validation','test_main_smoke','test_strategy_comparison_smoke','test_strategy_plan_consistency','test_execution_time_breakdown','test_navigation_time_path_basis','test_planned_execution_consistency','test_path_length_decomposition','test_main_robot_unification','test_p5_fixture_geometry','test_dynamic_event_determinism','test_change_impact_locality','test_local_replan_preserves_unaffected_state','test_local_replan_fallback','test_local_replan_route_feasibility','test_visualization_smoke','test_path_cost_cache','test_sparse_cache_semantic_identity','test_independent_geometric_reachability','test_independent_reachability_audit','test_benchmark_protocol_scope','test_route_provenance_repair','test_protocol_dynamic_comparison','test_c2_1_path_repair','test_c2_4_1_dstar_correctness'},'stable');
files=cellfun(@(s)fullfile(root,'tests',[s '.m']),names,'UniformOutput',false);
r=runtests(files); rows=repmat(struct('name','','passed',false,'failed',false,'incomplete',false,'duration_s',0),numel(r),1);
for k=1:numel(r), rows(k)=struct('name',r(k).Name,'passed',r(k).Passed,'failed',r(k).Failed,'incomplete',r(k).Incomplete,'duration_s',r(k).Duration); end
out=fullfile(root,'results','repair_20261027'); if ~isfolder(out),mkdir(out);end
report=struct('phase','final','matlab_version',version,'total',numel(r),'passed',sum([r.Passed]),'failed',sum([r.Failed]),'incomplete',sum([r.Incomplete]),'tests',rows);
fid=fopen(fullfile(out,'final_validation.json'),'w','n','UTF-8'); fprintf(fid,'%s',jsonencode(report,'PrettyPrint',true)); fclose(fid);
fprintf('FINAL_GATE total=%d passed=%d failed=%d incomplete=%d\n',numel(r),sum([r.Passed]),sum([r.Failed]),sum([r.Incomplete])); assert(all([r.Passed]));
